// TEST-ONLY SHIM - not a real Express implementation, not part of the
// shipped backend package (backend/package.json declares the real
// "express" dependency; this directory is only added to NODE_PATH for the
// offline test run because this sandbox has no network access to actually
// `npm install`). Provides just enough surface for routes/webRisk.js to
// load and register its one real POST handler, which the test then invokes
// directly with hand-built req/res objects - the ROUTE HANDLER LOGIC BEING
// EXERCISED IS THE REAL, UNMODIFIED PRODUCTION CODE.

function Router() {
  const routes = [];
  const router = {
    _routes: routes,
    post(path, handler) {
      routes.push({ method: "POST", path, handler });
      return router;
    },
    get(path, handler) {
      routes.push({ method: "GET", path, handler });
      return router;
    },
    use() {
      return router;
    },
  };
  return router;
}

function express() {
  throw new Error("shim express(): not implemented - only express.Router()/json() are shimmed for route-level tests");
}
express.Router = Router;
express.json = () => (req, res, next) => next && next();

module.exports = express;
